create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,avatar_url text,role text not null default 'customer' check(role in ('customer','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,image_url text,is_active boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),category_id uuid references categories(id) on delete set null,name text not null,slug text unique not null,description text,short_description text,sku text unique not null,price numeric(12,2) not null check(price>=0),compare_at_price numeric(12,2),cost_price numeric(12,2),stock_quantity int not null default 0 check(stock_quantity>=0),low_stock_threshold int not null default 3,is_active boolean not null default true,is_featured boolean not null default false,is_new boolean not null default false,is_best_seller boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,image_url text not null,alt_text text,sort_order int not null default 0,is_primary boolean not null default false,created_at timestamptz not null default now());
create table if not exists product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,name text not null,sku text unique,price numeric(12,2),stock_quantity int not null default 0,attributes jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists tags(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null); create table if not exists product_tags(product_id uuid references products(id) on delete cascade,tag_id uuid references tags(id) on delete cascade,primary key(product_id,tag_id));
create table if not exists wishlists(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references profiles(id) on delete cascade,created_at timestamptz default now()); create table if not exists wishlist_items(wishlist_id uuid references wishlists(id) on delete cascade,product_id uuid references products(id) on delete cascade,created_at timestamptz default now(),primary key(wishlist_id,product_id));
create table if not exists carts(id uuid primary key default gen_random_uuid(),user_id uuid unique references profiles(id) on delete cascade,session_id text unique,created_at timestamptz default now(),updated_at timestamptz default now(),check(user_id is not null or session_id is not null)); create table if not exists cart_items(id uuid primary key default gen_random_uuid(),cart_id uuid not null references carts(id) on delete cascade,product_id uuid not null references products(id),variant_id uuid references product_variants(id),quantity int not null check(quantity>0),unit_price numeric(12,2),created_at timestamptz default now(),updated_at timestamptz default now(),unique(cart_id,product_id,variant_id));
create table if not exists shipping_zones(id uuid primary key default gen_random_uuid(),name text not null,shipping_fee numeric(12,2) not null,free_shipping_threshold numeric(12,2),is_active boolean default true,delivery_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists pricing_rules(id uuid primary key default gen_random_uuid(),min_quantity int not null check(min_quantity>0),max_quantity int,discount_type text not null check(discount_type in ('percentage','fixed')),discount_value numeric(12,2) not null default 0,priority int default 0,is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now(),check(max_quantity is null or max_quantity>=min_quantity));
create table if not exists orders(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete set null,order_number text unique not null default ('TL-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),status text not null default 'pending' check(status in ('pending','confirmed','preparing','shipped','delivered','cancelled')),payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','refunded')),subtotal numeric(12,2) not null,discount numeric(12,2) not null default 0,shipping_fee numeric(12,2) not null,total numeric(12,2) not null,customer_name text not null,customer_phone text not null,customer_email text,shipping_address jsonb not null,notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id) on delete cascade,product_id uuid references products(id) on delete set null,variant_id uuid references product_variants(id) on delete set null,product_name text not null,product_image text,quantity int not null check(quantity>0),unit_price numeric(12,2) not null,total_price numeric(12,2) not null);
create table if not exists reviews(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,rating int not null check(rating between 1 and 5),review_text text,approved boolean not null default false,created_at timestamptz default now(),unique(product_id,user_id));
create table if not exists addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references profiles(id) on delete cascade,label text,governorate text,city text,address_line text,building text,apartment text,notes text,created_at timestamptz default now());
create table if not exists site_content(key text primary key,value jsonb not null default '{}',updated_at timestamptz default now());
create index if not exists products_category_idx on products(category_id); create index if not exists products_active_idx on products(is_active); create index if not exists products_search_idx on products using gin(to_tsvector('simple',coalesce(name,'')||' '||coalesce(sku,'')||' '||coalesce(description,''))); create index if not exists orders_user_idx on orders(user_id); create index if not exists order_items_order_idx on order_items(order_id);
